41	/**
42	 * Setting datatypes that "toggle" through a fixed list of options
43	 * (e.g. an enum or true/false) rather than allowing for free form input
44	 * (like a number or string).
45	 */
46	export const TOGGLE_TYPES: ReadonlySet<SettingsType | undefined> = new Set([
47	  'boolean',
48	  'enum',
49	]);
