67	export interface SettingCollectionDefinition {
68	  type: SettingsType;
69	  description?: string;
70	  properties?: SettingsSchema;
71	  /** Enum type options  */
72	  options?: readonly SettingEnumOption[];
73	  /**
74	   * Optional reference identifier for generators that emit a `$ref`.
75	   * For example, a JSON schema generator can use this to point to a shared definition.
76	   */
77	  ref?: string;
78	  /**
79	   * Optional merge strategy for dynamically added properties.
80	   * Used when this collection definition is referenced via additionalProperties.
81	   */
82	  mergeStrategy?: MergeStrategy;
83	}
84	
85	export enum MergeStrategy {
86	  // Replace the old value with the new value. This is the default.
87	  REPLACE = 'replace',
88	  // Concatenate arrays.
89	  CONCAT = 'concat',
90	  // Merge arrays, ensuring unique values.
91	  UNION = 'union',
92	  // Shallow merge objects.
93	  SHALLOW_MERGE = 'shallow_merge',
94	}
