66	  coreStatus: CoreToolCallStatus,
67	): ToolCallStatus {
68	  switch (coreStatus) {
69	    case CoreToolCallStatus.Validating:
70	      return ToolCallStatus.Pending;
71	    case CoreToolCallStatus.AwaitingApproval:
72	      return ToolCallStatus.Confirming;
73	    case CoreToolCallStatus.Executing:
