78	      return ToolCallStatus.Canceled;
79	    case CoreToolCallStatus.Error:
80	      return ToolCallStatus.Error;
81	    case CoreToolCallStatus.Scheduled:
82	      return ToolCallStatus.Pending;
83	    default:
84	      return checkExhaustive(coreStatus);
